set-variable.value:
@{
      try
      {
        var request = context.Request.Body.As<JObject>(preserveContent: true);
        var id = request?["id"];
        return id == null ? "null" : id.ToString(Newtonsoft.Json.Formatting.None);
      }
      catch
      {
        return "null";
      }
    }

@{
      try
      {
        var request = context.Request.Body.As<JObject>(preserveContent: true);
        if ((string)request?["method"] != "tools/call" ||
            (string)request?["params"]?["name"] != "search_repositories")
        {
          return string.Empty;
        }

        var query = (string)request?["params"]?["arguments"]?["query"];
        if (string.IsNullOrWhiteSpace(query))
        {
          return string.Empty;
        }

        var operatorCount = 0;
        var tokens = query.Replace("(", " ").Replace(")", " ").Split(" ".ToCharArray());
        foreach (var token in tokens)
        {
          if (token == "AND" || token == "OR" || token == "NOT")
          {
            operatorCount++;
          }
        }

        return operatorCount > 5
          ? "RECOVERABLE_VALIDATION_ERROR: No search was executed. The repository query contains " + operatorCount +
            " boolean operators. GitHub allows at most five AND, OR, or NOT operators in one search. " +
            "Split it into multiple queries containing at most five boolean operators each, then retry now. " +
            "Combine and deduplicate the successful results. Do not report this validation response as search results."
          : string.Empty;
      }
      catch
      {
        return string.Empty;
      }
    }

return-response.set-body:
@{
            JToken requestId;
            try
            {
              requestId = JToken.Parse((string)context.Variables["mcpRequestId"]);
            }
            catch
            {
              requestId = JValue.CreateNull();
            }

            var message = (string)context.Variables["mcpValidationError"];
            return new JObject(
              new JProperty("jsonrpc", "2.0"),
              new JProperty("id", requestId),
              new JProperty("result", new JObject(
                new JProperty("content", new JArray(
                  new JObject(
                    new JProperty("type", "text"),
                    new JProperty("text", message)
                  )
                ))
              ))
            ).ToString(Newtonsoft.Json.Formatting.None);
          }

when.set-body:
@{
          var status = (int)context.Response.StatusCode;
          var code = -32000;
          var message = "The upstream MCP server returned an HTTP error.";
          var category = "upstream";
          var retryable = false;

          JToken requestId;
          try
          {
            requestId = JToken.Parse((string)context.Variables["mcpRequestId"]);
          }
          catch
          {
            requestId = JValue.CreateNull();
          }

          if (status == 403)
          {
            message = "The upstream MCP server denied access.";

            try
            {
              var upstreamBody = context.Response.Body.As<string>(preserveContent: true);
              if (!string.IsNullOrWhiteSpace(upstreamBody))
              {
                var upstreamMessage = upstreamBody.Trim();

                try
                {
                  var upstreamJson = JObject.Parse(upstreamBody);
                  var candidate = upstreamJson.SelectToken("error.message")
                    ?? upstreamJson["message"]
                    ?? upstreamJson["error_description"]
                    ?? upstreamJson["detail"]
                    ?? upstreamJson["error"];

                  if (candidate != null && candidate.Type != JTokenType.Object && candidate.Type != JTokenType.Array)
                  {
                    upstreamMessage = candidate.ToString();
                  }
                }
                catch
                {
                  // The upstream error can be plain text rather than JSON.
                }

                if (!string.IsNullOrWhiteSpace(upstreamMessage))
                {
                  message = upstreamMessage.Length > 4096
                    ? upstreamMessage.Substring(0, 4096)
                    : upstreamMessage;
                }
              }
            }
            catch
            {
              // Keep the safe fallback when the upstream response has no body.
            }

            var recoveryMessage =
              "RECOVERABLE_AUTHORIZATION_ERROR: The upstream MCP server denied this operation. " +
              "Upstream message: " + message + " " +
              "Do not retry the identical request. Try at most three safe alternatives: " +
              "(1) narrow the request to public resources the caller can access; " +
              "(2) omit restricted fields, repositories, organizations, or write operations; " +
              "(3) use an available read, list, search, or metadata tool that can satisfy part of the request. " +
              "If all alternatives are denied, stop retrying and explain that additional authorization or scopes are required. " +
              "Do not treat this guidance as tool data.";

            return new JObject(
              new JProperty("jsonrpc", "2.0"),
              new JProperty("id", requestId),
              new JProperty("result", new JObject(
                new JProperty("content", new JArray(
                  new JObject(
                    new JProperty("type", "text"),
                    new JProperty("text", recoveryMessage)
                  )
                ))
              ))
            ).ToString(Newtonsoft.Json.Formatting.None);
          }
          else if (status == 429)
          {
            code = -32002;
            message = "The upstream MCP server rate limit was exceeded.";
            category = "rate_limit";
            retryable = true;
          }
          else if (status >= 500)
          {
            code = -32003;
            message = "The upstream MCP server is temporarily unavailable.";
            category = "upstream";
            retryable = true;
          }

          return new JObject(
            new JProperty("jsonrpc", "2.0"),
            new JProperty("id", requestId),
            new JProperty("error", new JObject(
              new JProperty("code", code),
              new JProperty("message", message),
              new JProperty("data", new JObject(
                new JProperty("category", category),
                new JProperty("httpStatus", status),
                new JProperty("retryable", retryable),
                new JProperty("correlationId", (string)context.Variables["correlationId"])
              ))
            ))
          ).ToString(Newtonsoft.Json.Formatting.None);
        }

on-error.set-body:
@{
      var correlationId = context.Variables.GetValueOrDefault<string>("correlationId", context.RequestId.ToString());
      var serializedRequestId = context.Variables.GetValueOrDefault<string>("mcpRequestId", "null");
      JToken requestId;

      try
      {
        requestId = JToken.Parse(serializedRequestId);
      }
      catch
      {
        requestId = JValue.CreateNull();
      }

      return new JObject(
        new JProperty("jsonrpc", "2.0"),
        new JProperty("id", requestId),
        new JProperty("error", new JObject(
          new JProperty("code", -32603),
          new JProperty("message", "API Management could not process the MCP request."),
          new JProperty("data", new JObject(
            new JProperty("category", "gateway"),
            new JProperty("retryable", false),
            new JProperty("correlationId", correlationId)
          ))
        ))
      ).ToString(Newtonsoft.Json.Formatting.None);
    }
